-- ============================================================================
-- 20261007120000__risk_flags
-- ============================================================================
-- The risk surface's storage. Everything the map, the detail sheet and route
-- scoring read comes from this table.
--
-- Forward-only. Do not edit this file once it has been applied anywhere —
-- scripts/migrate.py records a checksum and refuses to run if it changes.
-- Correct a mistake with a new migration.
--
-- Contract: backend/app/contracts/risk.py :: RiskFlag
-- Mirror:   frontend/src/types/contracts/risk.ts
-- ============================================================================

-- PostGIS lives in `extensions` on Supabase, matching SCHEMA.sql. The schema
-- already exists there, so the first line is a no-op against the real database;
-- it is here so this migration also applies to a plain Postgres, which is what
-- makes it testable against a throwaway container before it touches Supabase.
create schema if not exists extensions;
create extension if not exists postgis with schema extensions;


create table if not exists public.risk_flags (
    flag_id            uuid primary key default gen_random_uuid(),

    -- Dedup identity. Four outlets reporting one fire share an event_key, so
    -- they corroborate rather than multiply. Assigned by Rumour Guard (D05);
    -- until then every flag gets its own.
    event_key          text        not null,

    kind               text        not null,
    status             text        not null default 'unconfirmed',

    -- geography, not geometry: distances come back in metres on a sphere, which
    -- is what every caller actually wants. geometry would return degrees.
    location           extensions.geography(Point, 4326) not null,
    radius_m           integer     not null,

    -- Severity at observed_at, 0-100. What a client is served is this value
    -- decayed to the moment of the request. It is never stored decayed, because
    -- then every row would need rewriting on a timer.
    severity_0         double precision not null,

    half_life_hours    double precision not null,

    observed_at        timestamptz not null,

    -- DERIVED. Set by trg_risk_flags_expires_at below, which overwrites whatever
    -- the caller supplied. See that trigger for why it is a trigger and not a
    -- generated column.
    expires_at         timestamptz not null,

    -- D09: an announced procession is a claim about a window in the future.
    -- Nullable, because a flag read out of today's news has neither.
    valid_from         timestamptz,
    valid_to           timestamptz,

    source_count       integer     not null default 1,
    sources            jsonb       not null default '[]'::jsonb,

    -- Written ONLY by app/policy/framing.py :: to_mobility_statement().
    -- Nothing else in the codebase may produce this string — not an agent, not
    -- an LLM, not a fixture file. tests/invariants/ enforces that.
    mobility_statement text        not null,

    -- 24 hour-of-day multipliers. Null means neutral. D02 fills these in.
    time_profile       jsonb,

    created_at         timestamptz not null default now(),
    updated_at         timestamptz not null default now(),

    -- ---- invariants, at the level that cannot be bypassed ------------------

    -- "Decay by default. No permanent area labels." Concept document §9,
    -- IMPLEMENTATION_PLAN.md §4. This is the one CHECK the plan names
    -- explicitly, and it is not optional.
    constraint risk_flags_half_life_positive
        check (half_life_hours > 0),

    -- "Verification before publication. No single unverified source produces a
    -- confirmed flag." Enforced in Rumour Guard (D05), in an invariant test, and
    -- here. Three layers for one rule is deliberate: it is the claim a judge is
    -- most likely to press on, and the strongest honest answer is that the
    -- database itself will not store the violation.
    constraint risk_flags_confirmed_needs_two_sources
        check (status <> 'confirmed' or source_count >= 2),

    constraint risk_flags_status_check
        check (status in ('unconfirmed', 'confirmed', 'expired', 'rejected')),

    -- Mirrors IncidentKind. text + CHECK rather than a Postgres enum on purpose:
    -- adding a kind is then an ordinary ALTER inside a transaction, where
    -- `alter type ... add value` is not.
    constraint risk_flags_kind_check
        check (kind in (
            'road_accident', 'fire', 'clash', 'blockade', 'procession',
            'waterlogging', 'construction', 'utility_outage', 'chronic', 'other'
        )),

    constraint risk_flags_radius_sane
        check (radius_m > 0 and radius_m <= 20000),

    constraint risk_flags_severity_range
        check (severity_0 >= 0 and severity_0 <= 100),

    constraint risk_flags_source_count_min
        check (source_count >= 1),

    -- A flag may cite fewer SourceRefs than its source_count (Rumour Guard can
    -- count a corroboration it does not keep the full text of) but never more.
    constraint risk_flags_sources_match_count
        check (jsonb_array_length(sources) <= source_count),

    constraint risk_flags_validity_window_ordered
        check (valid_from is null or valid_to is null or valid_to > valid_from)
);


-- ---------------------------------------------------------------------------
-- expires_at is derived, and callers cannot set it
-- ---------------------------------------------------------------------------
-- IMPLEMENTATION_PLAN.md §6.1: `expires_at` is "derived, never hand-set".
--
-- The obvious implementation is a GENERATED column, and it does not work:
-- `timestamptz + interval` is STABLE rather than IMMUTABLE in Postgres (adding
-- an interval depends on the session time zone), and a generation expression
-- must be immutable. Postgres rejects it outright.
--
-- A BEFORE trigger gives the same guarantee without that restriction: whatever
-- the caller passes for expires_at is discarded and replaced. It also keeps ONE
-- implementation of the formula, and this is it. There is deliberately no Python
-- copy: two implementations of one rule is how the rule ends up meaning two
-- things. Python reads expires_at and never computes it.
--
-- The arithmetic: severity halves every `half_life_hours`, and a flag stops
-- being served once it falls below the serve threshold. Solving
-- severity_0 * 0.5^(t/H) = threshold for t gives
--
--     t = H * log2(severity_0 / threshold)
--
-- `greatest(severity_0, threshold)` keeps the logarithm defined and makes a flag
-- born below the threshold expire immediately, which is correct.
--
-- The `greatest(..., valid_to)` wrapper is what lets D09 work with no schema
-- change: a procession announced today for tomorrow evening must not expire
-- tonight merely because it was observed today.
--
-- The threshold is 5.0 on the 0-100 scale: below that a flag is not worth
-- showing. D02 needs the same number in Python to compute severity *now* for a
-- given `as_of`; when it does, it imports or mirrors this value and a comment goes
-- on both sides. Until then this function is the only place it exists.

create or replace function public.risk_flags_set_expires_at()
returns trigger
language plpgsql
as $$
declare
    threshold constant double precision := 5.0;
    hours     double precision;
begin
    hours := new.half_life_hours
             * ln(greatest(new.severity_0, threshold) / threshold)
             / ln(2.0);

    new.expires_at := greatest(
        new.observed_at + make_interval(secs => hours * 3600.0),
        coalesce(new.valid_to, new.observed_at)
    );

    return new;
end;
$$;

comment on function public.risk_flags_set_expires_at() is
    'Derives risk_flags.expires_at. Overwrites any supplied value — the column '
    'is derived by contract (IMPLEMENTATION_PLAN.md §6.1).';

drop trigger if exists trg_risk_flags_expires_at on public.risk_flags;
create trigger trg_risk_flags_expires_at
    before insert or update of observed_at, severity_0, half_life_hours, valid_to
    on public.risk_flags
    for each row execute function public.risk_flags_set_expires_at();


-- ---------------------------------------------------------------------------
-- Indexes
-- ---------------------------------------------------------------------------

-- Every map read is a bounding-box query. Without this it is a sequential scan.
create index if not exists idx_risk_flags_location
    on public.risk_flags using gist (location);

-- The serve query is "live flags, not yet expired" — the index the plan names.
create index if not exists idx_risk_flags_status_expires
    on public.risk_flags (status, expires_at);

-- Rumour Guard (D05) looks flags up by event identity to corroborate them.
create index if not exists idx_risk_flags_event_key
    on public.risk_flags (event_key);

-- D09 serves a forward-looking view. Partial, because almost no flag has a
-- validity window and an index over mostly-nulls is wasted space.
create index if not exists idx_risk_flags_validity
    on public.risk_flags (valid_from, valid_to)
    where valid_from is not null;

create index if not exists idx_risk_flags_observed_at
    on public.risk_flags (observed_at desc);


-- ---------------------------------------------------------------------------
-- updated_at
-- ---------------------------------------------------------------------------
-- public.set_updated_at() is created by SCHEMA.sql. Guarded so this migration
-- still applies to a database where SCHEMA.sql has not run yet.

do $$
begin
    if exists (
        select 1 from pg_proc p
        join pg_namespace n on n.oid = p.pronamespace
        where n.nspname = 'public' and p.proname = 'set_updated_at'
    ) then
        drop trigger if exists trg_risk_flags_updated_at on public.risk_flags;
        create trigger trg_risk_flags_updated_at
            before update on public.risk_flags
            for each row execute function public.set_updated_at();
    end if;
end $$;


-- ---------------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------------
-- Backend-only, like sos_incidents and user_locations. The app reads risk flags
-- through GET /api/v1/risk/flags, never through PostgREST, because the decay and
-- time-of-day arithmetic belongs in one place and the client is not that place.
--
-- RLS on with no policies means anon and authenticated cannot see the table at
-- all; the service-role connection the backend uses bypasses RLS.

alter table public.risk_flags enable row level security;

revoke all on public.risk_flags from anon, authenticated;


comment on table public.risk_flags is
    'The risk surface. One decaying, located claim about mobility per row. '
    'Contract: app/contracts/risk.py :: RiskFlag. Read via GET /api/v1/risk/flags.';

comment on column public.risk_flags.expires_at is
    'DERIVED by trg_risk_flags_expires_at from observed_at, severity_0, '
    'half_life_hours and valid_to. Never hand-set.';

comment on column public.risk_flags.mobility_statement is
    'Written only by app/policy/framing.py::to_mobility_statement(). '
    'Concept document §9: mobility framing, never judgment.';


notify pgrst, 'reload schema';
